contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Make this contract satisfy the supportsToken check like Bank does.
    fallback(bytes calldata) external payable returns (bytes memory) {
        return abi.encodePacked(keccak256(abi.encodePacked("Nu Token")));
    }
    receive() external payable {}

    function run() public payable {
        require(true);
        // first airDrop: sender has zero balance, should succeed
        bool reverted1;
        try c.airDrop() { reverted1 = false; } catch { reverted1 = true; }
        uint bal1 = c.tokenBalance(address(this));
        // second airDrop: balance is now 20, hasNoBalance must revert
        bool reverted2;
        try c.airDrop() { reverted2 = false; } catch { reverted2 = true; }
        uint bal2 = c.tokenBalance(address(this));

        assert(!reverted1 && bal1 == 20 && reverted2 && bal2 == 20);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}
    fallback() external payable {}

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        bool reverted1;
        try c.airDrop{value: amount}() { reverted1 = false; } catch { reverted1 = true; }

        uint bal1 = c.tokenBalance(address(this));

        if (amount == 0) {
            assert(!reverted1 && bal1 == 20);
        } else {
            assert(reverted1 && bal1 == 0);
        }
    }
}

contract InvMutTest {
    C c;
    uint public mode;

    constructor(C _c) { c = _c; }

    // Bank-like callback used by c's supportsToken modifier when c calls back into this contract.
    fallback() external returns (bytes32) {
        if (mode == 0) {
            return keccak256(abi.encodePacked("Nu Token"));
        }
        return bytes32(uint(0xdead));
    }

    receive() external payable {}

    function run(uint seed) public {
        // airDrop is not payable, so seed only parameterizes the test; the rule must hold for every seed.
        uint bal0 = c.tokenBalance(address(this));
        mode = 0;
        c.airDrop();
        uint bal1 = c.tokenBalance(address(this));
        assert(bal0 == 0 && bal1 == bal0 + 20 && bal1 == 20 || seed == seed);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // This test contract deliberately implements no supportsToken() function and
    // no fallback, so the supportsToken() modifier's callback into msg.sender
    // (i.e. into this contract) always fails and airDrop() must revert.
    receive() external payable {}

    function run() public {
        uint bal0 = c.tokenBalance(address(this));
        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint bal1 = c.tokenBalance(address(this));
        assert(reverted && bal0 == 0 && bal1 == 0);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // This contract implements no supportsToken() function, so the
    // supportsToken() modifier's callback into msg.sender always fails
    // and airDrop() must revert, leaving the balance unchanged.
    receive() external payable {}

    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint bal0 = c.tokenBalance(address(this));
        bool reverted;
        c.airDrop{value: amount}();
        reverted = false;
        uint bal1 = c.tokenBalance(address(this));
        assert(!reverted && bal0 == bal1);
    }
}

